      "claim": "S-RCP solution formulation had 65% absolute oral bioavailability in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Rufloxacin oral bioavailability in humans is at least 50%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Brigatinib oral bioavailability was approximately 46% in healthy volunteers, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental records report human absolute oral bioavailability values of at least 46%, with most above 50% and one near 100%; no retrieved evidence supports F<20%. Therefore high bioavailability at the F>=20% threshold is better supported.",
